                TestLogger.logger.debug("Request [" + request1 + "] #1:  ....Future response [" + futureResult + "]...");
            }
        } catch (Exception exc) {
            TestLogger.logger.debug("Request [" + request1 + "] :  got exception [" + exc.getClass().getName() + "]  [" + exc.getMessage() + "] ");
